  const sorted = nums.slice();
  const buffer = new Array(nums.length);
  const countPairs = (low, high) => {
    if (high - low <= 1) {
      return 0;
    }
    const mid = Math.floor((low + high) / 2);
    let count = countPairs(low, mid) + countPairs(mid, high);
    let j = mid;
    for (let i = low; i < mid; i++) {
      while (j < high && sorted[i] > 2 * sorted[j]) {
        j++;
      }
      count += j - mid;
    }
    let left = low;
    let right = mid;
    let k = low;
    while (left < mid || right < high) {
      if (right === high || (left < mid && sorted[left] <= sorted[right])) {
        buffer[k++] = sorted[left++];
      } else {
        buffer[k++] = sorted[right++];
      }
    }
    for (let t = low; t < high; t++) {
      sorted[t] = buffer[t];
    }
    return count;
  };
  return countPairs(0, nums.length);
}

